from pysat.solvers import Glucose4
from pysat.card import CardEnc
import itertools

n = 23
edges = []
edge_vars = {}
var_counter = 1

for i in range(n):
    for j in range(i+1, n):
        edge_vars[(i, j)] = var_counter
        var_counter += 1

# 3-colorable
# color_vars[i][c]
color_vars = {}
for i in range(n):
    for c in range(3):
        color_vars[(i, c)] = var_counter
        var_counter += 1

solver = Glucose4()

# Each vertex has exactly one color
for i in range(n):
    solver.add_clause([color_vars[(i, 0)], color_vars[(i, 1)], color_vars[(i, 2)]])
    solver.add_clause([-color_vars[(i, 0)], -color_vars[(i, 1)]])
    solver.add_clause([-color_vars[(i, 0)], -color_vars[(i, 2)]])
    solver.add_clause([-color_vars[(i, 1)], -color_vars[(i, 2)]])

# Edge implies different colors
for i in range(n):
    for j in range(i+1, n):
        e = edge_vars[(i, j)]
        for c in range(3):
            solver.add_clause([-e, -color_vars[(i, c)], -color_vars[(j, c)]])

# No triangles
for i, j, k in itertools.combinations(range(n), 3):
    solver.add_clause([-edge_vars[(i, j)], -edge_vars[(j, k)], -edge_vars[(i, k)]])

# No 4-cycles
for i, j, k, l in itertools.combinations(range(n), 4):
    # i-j-k-l-i
    solver.add_clause([-edge_vars[(i, j)], -edge_vars[(j, k)], -edge_vars[(k, l)], -edge_vars[(i, l)]])
    # i-j-l-k-i
    solver.add_clause([-edge_vars[(i, j)], -edge_vars[(j, l)], -edge_vars[(k, l)], -edge_vars[(i, k)]])
    # i-k-j-l-i
    solver.add_clause([-edge_vars[(i, k)], -edge_vars[(j, k)], -edge_vars[(j, l)], -edge_vars[(i, l)]])

# At least 44 edges
edge_var_list = [edge_vars[(i, j)] for i in range(n) for j in range(i+1, n)]
cnf = CardEnc.atleast(lits=edge_var_list, bound=44, top_id=var_counter)
for clause in cnf.clauses:
    solver.add_clause(clause)

if solver.solve():
    model = solver.get_model()
    res_edges = []
    for i in range(n):
        for j in range(i+1, n):
            if model[edge_vars[(i, j)] - 1] > 0:
                res_edges.append((i, j))
    print(res_edges)
else:
    print("UNSAT")

