def is_3_colorable(adj):
    colors = {}
    def dfs(u):
        if u == 23:
            return True
        for c in range(3):
            if all(colors.get(v) != c for v in adj[u]):
                colors[u] = c
                if dfs(u + 1):
                    return True
                del colors[u]
        return False
    return dfs(0)

